import type { State, Task } from "../model.js";
import { atomicWrite } from "./lock.js";
import { renderBacklog } from "./markdown-grammar.js";

function render(tasks: Task[], archive = false): string {
  const sections: [State, string][] = archive
    ? [["done", "Done"]]
    : [
        ["in_flight", "In flight"],
        ["queued", "Queued"],
        ["done", "Done"],
      ];
  return renderBacklog({
    finalNewline: true,
    preamble: [
      archive ? "# Done archive" : "# Backlog",
      "",
      "<!-- Generated by tasks-axi from beads; read-only. Do not edit. -->",
      "",
    ],
    sections: sections.map(([state, label]) => ({
      headerLine: `## ${label}`,
      state,
      entries: tasks
        .filter((task) => task.state === state)
        .map((task) => ({
          kind: "task" as const,
          task,
          raw: [],
          dirty: true,
        })),
    })),
  });
}

/** Caller holds the beads Store lock. Each replacement is atomic, not the pair. */
export function writeMarkdownMirror(
  tasks: Task[],
  path: string,
  archivePath: string,
  doneKeep: number,
): void {
  const done = tasks
    .filter((task) => task.state === "done")
    .sort((a, b) => (b.closed ?? "").localeCompare(a.closed ?? ""));
  const kept = new Set(done.slice(0, doneKeep).map((task) => task.id));
  // Archive first: a newly-evicted Done row reaches the archive before it leaves
  // the active projection. The database remains authoritative across a crash.
  atomicWrite(
    archivePath,
    render(
      done.filter((task) => !kept.has(task.id)),
      true,
    ),
  );
  atomicWrite(
    path,
    render(tasks.filter((task) => task.state !== "done" || kept.has(task.id))),
  );
}
